mapper.select:
SELECT invocation_key,accepted_at,observation,observation_digest FROM arte_ai_tool_execution_snapshot
WHERE owner_key=#{owner} AND accepted_at >= #{from} AND accepted_at < #{until}
AND binding_key=#{binding}
AND (accepted_at < #{afterAt} OR (accepted_at=#{afterAt} AND invocation_key <
    #{afterKey}))

ORDER BY accepted_at DESC,invocation_key DESC LIMIT #{limit}

SELECT workspace_snapshot FROM arte_ai_attempt WHERE invocation_key IN
#{key}
ORDER BY invocation_key,attempt_number

SELECT workspace_snapshot FROM arte_ai_settlement WHERE reservation_key IN
#{key}
LIMIT 2001

SELECT owner_key,invocation_key,attempt_key,payload_digest,charge_snapshot AS snapshot FROM arte_ai_tool_bill
WHERE owner_key=#{owner} AND invocation_key IN
#{key}
